package com.app.controller;
import com.app.dto.SharedExpenseDtos.*; import com.app.security.UserPrincipal; import com.app.service.SharedInvitationService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/personal/shared-expenses/invitations") @RequiredArgsConstructor
public class SharedInvitationController {private final SharedInvitationService service;@GetMapping public List<InvitationDto> inbox(@AuthenticationPrincipal UserPrincipal p){return service.inbox(p.getUserId());}@PostMapping("/groups/{groupId}") public InvitationDto invite(@AuthenticationPrincipal UserPrincipal p,@PathVariable Long groupId,@Valid @RequestBody InvitationRequest r){return service.invite(p.getAccountId(),p.getUserId(),groupId,r);}@PostMapping("/{id}/accept") public InvitationDto accept(@AuthenticationPrincipal UserPrincipal p,@PathVariable Long id){return service.respond(p.getUserId(),id,true);}@PostMapping("/{id}/decline") public InvitationDto decline(@AuthenticationPrincipal UserPrincipal p,@PathVariable Long id){return service.respond(p.getUserId(),id,false);}}
